const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], page=document.body.dataset.page, content=$('#content');let me=null, stats=null, allCourses=[], currentCourse=null, currentLessons=[], activeLesson=null, chosen=null, filter='all';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,method='GET',body){let res=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(body!==undefined?{body:JSON.stringify(body)}:{})});let x=await res.json();if(!res.ok||x.success===false)throw Error(x.error||'Não foi possível completar a solicitação.');return x}
function msg(s){$('#flash').hidden=false;$('#flash').textContent=s;$('#flash').scrollIntoView({block:'nearest'})}function fail(e){msg(e.message||String(e))}function loginNeeded(){if(me)return false;msg('Entre na sua conta para salvar seu progresso.');return true}
function heading(label,title,subtitle=''){return `<div class="page-head"><span class="tag">${label}</span><h1>${title}</h1><p>${subtitle}</p></div>`}function statsHTML(s){return `<div class="stats"><div class="stat"><span class="bubble">▤</span><div><small>Aulas concluídas</small><strong>${s.completed}</strong></div></div><div class="stat"><span class="bubble">✦</span><div><small>Experiência (XP)</small><strong>${s.xp}</strong></div></div><div class="stat"><span class="bubble">♕</span><div><small>Certificados</small><strong>${s.certificates}</strong></div></div></div>`}
function card(c){let pct=Math.round(c.done/c.total*100);return `<article class="card" data-search="${esc((c.name+' '+c.description+' '+c.category).toLowerCase())}"><div class="cover">${esc(c.name.split(' ')[0].slice(0,5))}</div><div class="card-body"><span class="tag">${esc(c.level)} • ${esc(c.category)} • ${c.hours}h</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="progress"><span style="width:${pct}%"></span></div><small class="small">${c.done}/${c.total} aulas • ${pct}%</small><div class="course-actions"><a class="card-link" href="/curso/${encodeURIComponent(c.id)}">Acessar curso →</a><button class="chip" data-favorite="${esc(c.id)}" aria-pressed="${!!c.favorite}" aria-label="${c.favorite?'Remover dos':'Adicionar aos'} favoritos: ${esc(c.name)}">${c.favorite?'★ Salvo':'☆ Favoritar'}</button></div></div></article>`}
