function coursesPage(){let categories=[...new Set(allCourses.map(c=>c.category))].sort();content.innerHTML=heading('TRILHAS DE APRENDIZAGEM','Cursos completos','Pesquise por linguagem, categoria ou nível e acompanhe sua evolução.')+`<div class="filters course-filters"><label>Nível <select class="field" id="level-filter"><option value="all">Todos</option>${[...new Set(allCourses.map(c=>c.level))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Categoria <select class="field" id="category-filter"><option value="all">Todas</option>${categories.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="favorite-label"><input type="checkbox" id="favorites-only"> Somente favoritos</label></div><p id="courses-count" class="small" role="status"></p><div class="grid" id="courses-grid"></div>`;$('#level-filter').onchange=e=>{filter=e.target.value;renderCourseGrid()};$('#category-filter').onchange=e=>{categoryFilter=e.target.value;renderCourseGrid()};$('#favorites-only').onchange=e=>{favoriteFilter=e.target.checked;renderCourseGrid()};renderCourseGrid()}
function renderCourseGrid(){let arr=allCourses.filter(c=>(filter==='all'||c.level===filter)&&(categoryFilter==='all'||c.category===categoryFilter)&&(!favoriteFilter||c.favorite));$('#courses-count').textContent=arr.length+' cursos encontrados';$('#courses-grid').innerHTML=arr.map(card).join('')||'<p class="empty">Nenhum curso encontrado com esses filtros.</p>';$$('[data-favorite]').forEach(b=>b.onclick=async()=>{if(loginNeeded())return;try{let x=await api('/data/courses/'+encodeURIComponent(b.dataset.favorite)+'/favorite','POST');let c=allCourses.find(c=>c.id===b.dataset.favorite);c.favorite=x.favorite;renderCourseGrid();msg(x.favorite?'Curso adicionado aos favoritos.':'Curso removido dos favoritos.')}catch(e){fail(e)}});search()}
function dashboard(){content.innerHTML=`<section class="hero"><span class="eyebrow">✦ APRENDA, CRIE, CONQUISTE</span><h1>Seu futuro na tecnologia<br>começa aqui.</h1><p>Trilhas completas, desafios práticos, mentoria e oportunidades em um só lugar.</p><a class="btn dark-btn" href="/cursos">Explorar cursos ↗</a></section>`+statsHTML(stats)+`<div class="section-title"><h2>Continue aprendendo</h2><a href="/cursos">Ver todos →</a></div><div class="grid">${allCourses.slice(0,3).map(card).join('')}</div><div class="section-title"><h2>Descubra mais</h2></div><div class="feature-grid"><a class="panel" href="/tutora"><h3>✦ Tutora de programação</h3><p>Tire dúvidas e aprenda com explicações passo a passo.</p><b class="link">Começar →</b></a><a class="panel" href="/certificados"><h3>♕ Certificados digitais</h3><p>Conclua cursos e imprima seus certificados em PDF.</p><b class="link">Explorar →</b></a></div>`}
async function coursePage(){let cid=document.body.dataset.course;currentCourse=await api('/data/course/'+encodeURIComponent(cid));currentLessons=currentCourse.lessons;content.innerHTML=`<p><a class="link" href="/trilha-personalizada">← Minha trilha</a></p>`+heading('JORNADA DE APRENDIZAGEM',esc(currentCourse.name),esc(currentCourse.description))+`<div class="course-summary panel"><span class="tag">${esc(currentCourse.category)} • ${currentCourse.hours} horas estimadas</span><p>${currentLessons.filter(x=>x.completed).length} de ${currentLessons.length} aulas concluídas</p></div><div class="lesson-layout"><div class="lesson-nav" id="lesson-nav"></div><div class="panel lesson-panel" id="lesson-panel"></div></div><section class="panel final-project"><h3>Projeto prático final: ${esc(currentCourse.finalProject.title)}</h3><p>${esc(currentCourse.finalProject.description)}</p><ol>${currentCourse.finalProject.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>Critérios de revisão</h4><p>${currentCourse.finalProject.criteria.map(esc).join(' • ')}</p><small>Projeto orientado para portfólio; a avaliação automática atual é feita pelos questionários das aulas e módulos.</small></section><div class="panel" style="margin-top:15px"><h3>Certificado deste curso</h3><p>Conclua as aulas e passe nas avaliações finais dos módulos.</p><button class="btn" id="issue-cert">Emitir certificado</button></div>`;let groups=currentCourse.modules;$('#lesson-nav').innerHTML=groups.map((m,i)=>`<section class="map-module ${m.unlocked?'':'map-locked'}"><h3>${m.passed?'✓':m.unlocked?'◉':'🔒'} ${esc(m.name)}</h3><p class="small">${m.done}/${m.total} aulas • ${m.passed?'Avaliação aprovada':m.unlocked?'Disponível':'Bloqueado'}</p>${currentLessons.filter(l=>l.module===m.name).map(l=>`<button data-lid="${esc(l.id)}" ${l.locked?'disabled':''}>${l.completed?'✓':l.locked?'🔒':'○'} ${esc(l.title)}</button>`).join('')}${m.unlocked&&m.done===m.total&&!m.passed?`<button class="btn" data-assess="${esc(m.name)}">Avaliação do módulo →</button>`:''}</section>`).join('');$$('[data-lid]').forEach(b=>b.onclick=()=>showLesson(b.dataset.lid));$$('[data-assess]').forEach(b=>b.onclick=()=>showAssessment(b.dataset.assess));$('#issue-cert').onclick=()=>issue(cid);let requested=new URLSearchParams(location.search).get('aula');let first=currentLessons.find(l=>!l.locked&&!l.completed)||currentLessons.find(l=>!l.locked);if(requested&&currentLessons.some(l=>l.id===requested&&!l.locked))first=currentLessons.find(l=>l.id===requested);let pending=groups.find(m=>m.unlocked&&m.done===m.total&&!m.passed);if(pending&&!currentLessons.some(l=>!l.locked&&!l.completed))await showAssessment(pending.name);else if(first)await showLesson(first.id);else $('#lesson-panel').textContent='Trilha concluída! Você já pode emitir seu certificado.'}
async function showAssessment(name){let cid=currentCourse.id,ls=currentLessons.filter(l=>l.module===name),last=ls[ls.length-1];let l=await api('/data/lesson/'+encodeURIComponent(last.id));chosen=null;$('#lesson-panel').innerHTML=`<span class="tag">AVALIAÇÃO FINAL</span><h2>${esc(name)}</h2><p>Responda para desbloquear o próximo módulo. Você pode tentar novamente.</p><p><strong>${esc(l.question)}</strong></p><div id="choices">${l.options.map((o,i)=>`<button class="option" data-choice="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="btn" id="answer">Enviar avaliação</button><p id="answer-msg" role="status"></p>`;$$('[data-choice]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.choice);$$('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b))});$('#answer').onclick=async()=>{if(chosen===null)return msg('Selecione uma resposta.');try{let r=await api('/data/course/'+encodeURIComponent(cid)+'/module/assessment','POST',{module:name,choice:chosen});$('#answer-msg').textContent=r.message+' '+r.explanation;if(r.correct){msg(r.message);await coursePage()}}catch(e){fail(e)}}}
async function showLesson(id){activeLesson=id;chosen=null;$$('[data-lid]').forEach(b=>b.classList.toggle('active',b.dataset.lid===id));let l=await api('/data/lesson/'+encodeURIComponent(id));$('#lesson-panel').innerHTML=`<span class="tag">${esc(l.module)}</span><h2>${esc(l.title)}</h2><p class="lesson-body">${esc(l.body)}</p><h3>Objetivos da aula</h3><ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Conceitos importantes</h3><ul>${l.theory.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Pratique</h3><p>${esc(l.practice)}</p><h3>Desafio</h3><p>${esc(l.challenge)}</p><h3>Verifique o que aprendeu</h3><p><strong>${esc(l.question)}</strong></p><div id="choices">${l.options.map((o,i)=>`<button class="option" data-choice="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="btn" id="answer">Conferir e concluir aula</button><p class="small" id="answer-msg" role="status"></p>`;$$('[data-choice]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.choice);$$('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b))});$('#answer').onclick=async()=>{if(loginNeeded())return;if(chosen===null)return msg('Escolha uma alternativa.');try{let result=await api('/data/lesson/'+encodeURIComponent(id)+'/answer','POST',{choice:chosen});$('#answer-msg').textContent=result.message+' '+result.explanation;if(result.correct){await refresh();await coursePage()}}catch(e){fail(e)}}}
