async function profilePage(){content.innerHTML=heading('MINHA EVOLUÇÃO','Meu perfil e desempenho','Acompanhe suas aulas, resultados das avaliações e evolução no tempo.')+`<div class="panel"><h3 id="user-name">${esc(me?.name||'Visitante')}</h3><p>${esc(me?.email||'Entre na sua conta para editar o perfil.')}</p><form id="profile-form"><label class="label" for="edit-name">Seu nome</label><input class="field" id="edit-name" value="${esc(me?.name||'')}" maxlength="90" required><button class="btn">Salvar alterações</button></form><button class="btn ghost" id="logout" style="margin-top:12px">Sair da conta</button></div>`+statsHTML(stats)+`<div class="chart-row"><div class="panel"><h3>Conclusão por curso</h3><canvas class="chart" id="chart-courses" role="img" aria-label="Gráfico de aulas concluídas por curso"></canvas><div id="chart-table" class="small"></div></div><div class="panel"><h3>Atividade de estudo</h3><canvas class="chart" id="chart-activity" role="img" aria-label="Gráfico de aulas concluídas por dia"></canvas><p class="small">Acerto nas avaliações: ${stats.accuracy}% • ${stats.attempts} tentativas</p></div></div>`;$('#profile-form').onsubmit=async e=>{e.preventDefault();if(loginNeeded())return;try{await api('/data/profile','POST',{name:$('#edit-name').value});await refresh();msg('Nome atualizado!')}catch(e){fail(e)}};$('#logout').onclick=async()=>{await api('/auth/logout','POST',{});location.href='/entrar'};drawCharts();await renderPerformance()}
function drawBars(canvas,values,labels,max){let ctx=canvas.getContext('2d'),dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let accent=getComputedStyle(document.body).getPropertyValue('--accent').trim(),muted=getComputedStyle(document.body).getPropertyValue('--muted').trim();let gap=8,bar=(w-35)/Math.max(values.length,1),top=25;ctx.fillStyle=muted;ctx.font='11px sans-serif';ctx.fillText(String(max),4,15);values.forEach((v,i)=>{let height=(h-65)*(v/(max||1)),x=30+i*bar;ctx.fillStyle=accent;ctx.fillRect(x,h-34-height,Math.max(5,bar-gap),height);ctx.fillStyle=muted;ctx.fillText(String(labels[i]).slice(0,6),x,h-16)})}
function drawCharts(){let courses=stats.per_course.filter(x=>x.done>0).slice(0,7);if(!courses.length)courses=stats.per_course.slice(0,6);drawBars($('#chart-courses'),courses.map(x=>Math.round(x.done/x.total*100)),courses.map(x=>x.name),100);$('#chart-table').textContent=courses.map(x=>`${x.name}: ${x.done}/${x.total}`).join(' • ');let a=stats.activity;drawBars($('#chart-activity'),a.map(x=>x.count),a.map(x=>x.date.slice(5)),Math.max(1,...a.map(x=>x.count)));window.onresize=()=>{if(page==='profile')drawCharts()}}
