 code.addEventListener('input',()=>{renderCode();localStorage.setItem('ce-code-'+lang.value,getCode().slice(0,50000));});code.addEventListener('scroll',renderCode);code.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();let a=code.selectionStart,b=code.selectionEnd;code.setRangeText('  ',a,b,'end');renderCode()}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();$('#run-code').click()}});
 lang.onchange=()=>{projectId=null;currentChallenge=null;setLang(lang.value)};setLang('javascript');
 async function check(){try{let l=lang.value;if(l==='javascript'){new Function(getCode());output('✓ Sintaxe JavaScript válida.');return true}if(l==='html'){output('HTML pronto para pré-visualização. Scripts não serão executados.');return true}if(l==='css'){output('CSS pronto para pré-visualização.');return true}let url=l==='sql'?'/api/editor/sql':`/api/editor/${l}/check`;let x=await api(url,'POST',l==='sql'?{query:getCode()}:{code:getCode()});output(JSON.stringify(x,null,2));return !!(x.success??x.valid??true)}catch(e){output('Erro: '+e.message);return false}}
 $('#check').onclick=check;
 function clearPreview(){let host=$('#preview-host');host.replaceChildren();return host}
 function showPreview(){let host=clearPreview(),frame=document.createElement('iframe');frame.setAttribute('sandbox','');frame.setAttribute('referrerpolicy','no-referrer');frame.title='Prévia isolada';frame.className='lab-frame';let csp=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; form-action 'none'; base-uri 'none'">`;frame.srcdoc=csp+(lang.value==='css'?'<h1>Prévia CSS</h1><p>Teste seu estilo nesta página.</p><style>'+getCode().replace(/<\/style/gi,'')+'</style>':getCode());host.append(frame);output('Prévia carregada em iframe isolado, sem execução de scripts.');}
 function runJS(tests){return new Promise(resolve=>{let frame=document.createElement('iframe'),token=crypto.randomUUID(),finished=false;frame.style.display='none';frame.setAttribute('sandbox','allow-scripts');frame.setAttribute('referrerpolicy','no-referrer');let timer=setTimeout(()=>finish({error:'Tempo limite de 2 segundos excedido.'}),2000);function finish(x){if(finished)return;finished=true;clearTimeout(timer);window.removeEventListener('message',listener);frame.remove();resolve(x)}function listener(e){if(e.source!==frame.contentWindow||!e.data||e.data.token!==token)return;finish(e.data.payload)}window.addEventListener('message',listener);let source=getCode();let harness=`const logs=[];const safe=(v)=>String(v).slice(0,1000);console.log=(...v)=>logs.push(v.map(safe).join(' '));let payload;try{const fn=new Function(${JSON.stringify(source)}+'\n'+${JSON.stringify(tests?tests.map(([expr])=>`return (${expr})`):[])}.join('\n'));if(false){});${tests?`const values=[];${tests.map(([expr])=>`values.push((new Function(${JSON.stringify(source+'\nreturn ('+expr+');')})()));`).join('')}payload={logs,values};`:`(new Function(${JSON.stringify(source)}) )();payload={logs};`}}catch(err){payload={error:String(err),logs}}parent.postMessage({token:${JSON.stringify(token)},payload},'*');`;frame.srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; connect-src 'none'; img-src 'none'; form-action 'none'"><script>${harness.replace(/<\/script/gi,'<\\/script')}<\/script>`;document.body.append(frame)} )}
 $('#run-code').onclick=async()=>{let l=lang.value;if(l==='html'||l==='css')return showPreview();if(l==='javascript'){output('Executando em ambiente isolado...');let r=await runJS();output(r.error?'Erro: '+r.error:r.logs.length?r.logs.join('\n'):'Executado sem saída no console.');return}if(l==='sql')return check();output('Execução indisponível para '+l+'. Use Verificar: o servidor não executa código enviado pelas alunas.');};
 $('#clear-code').onclick=()=>{if(!confirm('Limpar o código atual?'))return;setCode('');output('Editor limpo.');clearPreview()};
 async function listProjects(){if(!me){$('#project-list').textContent='Entre na sua conta para salvar e abrir projetos.';return}try{let r=await api('/data/editor/projects');$('#project-list').innerHTML=r.projects.map(p=>`<div class="lab-project"><span>${esc(p.title)} <small>(${esc(p.language)})</small></span><button class="chip" data-open="${p.id}">Abrir</button><button class="chip" data-delete="${p.id}">Excluir</button></div>`).join('')||'<p class="small">Nenhum projeto salvo.</p>';$$('[data-open]').forEach(b=>b.onclick=async()=>{try{let x=(await api('/data/editor/projects/'+b.dataset.open)).project;projectId=x.id;$('#project-title').value=x.title;setLang(x.language);setCode(x.code);output('Projeto aberto.')}catch(e){fail(e)}});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir este projeto?'))return;try{await api('/data/editor/projects/'+b.dataset.delete,'DELETE');if(String(projectId)===b.dataset.delete)projectId=null;await listProjects();msg('Projeto excluído.')}catch(e){fail(e)}})}catch(e){fail(e)}}
